%[text] ## 3. Plot Preprocessed Data
%[text] ### **3.1 Group VH2D-Wk22-02 (LU vs Kistler)**
%[text] #### **Run Wk22-02-01**
% --- Run Wk22-02-01: Single Figure / 2 Tiles with Dynamic Axis Limits ---
% DAQ-1
t1 = run_Wk22_02_01.DAQ_1.t_s;
y1_p = run_Wk22_02_01.DAQ_1.signal(:,1);
ch1_p = run_Wk22_02_01.DAQ_1.channels(1);
y1_tr = run_Wk22_02_01.DAQ_1.signal(:,2);
ch1_tr = run_Wk22_02_01.DAQ_1.channels(2);

% DAQ-4
t2 = run_Wk22_02_01.DAQ_4.t_s;
y2_p = run_Wk22_02_01.DAQ_4.signal(:,1);
ch2_p = run_Wk22_02_01.DAQ_4.channels(1);
y2_tr = run_Wk22_02_01.DAQ_4.signal(:,2);
ch2_tr = run_Wk22_02_01.DAQ_4.channels(2);

% Define Window Of Interest (WoI) explicitly (seconds)
LB_WoI = 0;% in seconds
UB_WoI = 0.25;% in seconds
WoI = [LB_WoI, UB_WoI];  % in seconds

% Create 2x1 tiled figure and naming
figId = "Fig-Wk22-02-01-LUvsKistler-PP-WoI-F01-Flush";
fig = figure( ... %[output:5765a154]
    'Name', figId, ... %[output:5765a154]
    'NumberTitle', 'off', ... %[output:5765a154]
    'Units','centimeters', ... %[output:5765a154]
    'Position',[10 10 36 20]); %[output:5765a154]

tiled = tiledlayout(2,1,'TileSpacing','compact','Padding','compact'); %[output:5765a154]
% Upper tile: pressures & triggers
% Left axis: pressures
axFull = nexttile; %[output:5765a154]
yyaxis(axFull, 'left'); %[output:5765a154]
hP1 = plot(axFull, t1, y1_p, 'Color', LUBlue, 'LineStyle', '-', 'LineWidth', 0.5);  %[output:5765a154]
hold(axFull,'on'); %[output:5765a154]
hP2 = plot(axFull, t2, y2_p, 'Color', LUCopper, 'LineStyle', '-', 'LineWidth', 0.5); %[output:5765a154]
ylabel(axFull, "Overpressure [kPa]", 'Interpreter', 'latex'); %[output:5765a154]
axFull.YColor = 'k'; %[output:5765a154]
% Right axis: triggers
yyaxis(axFull, 'right'); %[output:5765a154]
hTr1 = plot(axFull, t1, y1_tr, 'Color', Red_Dark, 'LineStyle', '-', 'LineWidth', 0.5);  %[output:5765a154]
hold(axFull,'on'); %[output:5765a154]
hTr2 = plot(axFull, t2, y2_tr, 'Color', Red_Light, 'LineStyle', ':', 'LineWidth', 0.5); %[output:5765a154]
ylabel(axFull, 'Trigger Voltage [V]', 'Interpreter', 'latex'); %[output:5765a154]
axFull.YColor = Red_Dark; %[output:5765a154]
% Common formatting
xlabel(axFull,'Time [s]', 'Interpreter', 'latex'); %[output:5765a154]
title(axFull,{'Preprocessed: Pressure $\&$ Trigger Signal',}, 'Interpreter', 'latex'); %[output:5765a154]

legend(axFull,[hP1,hP2,hTr1,hTr2], ... %[output:5765a154]
    {'Pressure (DAQ-1) '+ ch1_p,'Pressure (DAQ-4) ' + ch2_p,'Trigger (DAQ-1) ' + ch1_tr,'Trigger (DAQ-4) ' + ch2_tr}, ... %[output:5765a154]
    'Location','northeast', 'Interpreter','latex'); %[output:5765a154]

grid(axFull,'on'); %[output:5765a154]
hold(axFull,'off') %[output:5765a154]
% pbaspect(axFull, [16 9 1]);
% axFull.PlotBoxAspectRatioMode = 'manual';

% --- Dynamic axis limits (5% padding) ---
padFrac = 0.05;

% X limits combining t1 and t2
tAll = [t1(:); t2(:)];
tMin = min(tAll); tMax = max(tAll);
tRange = tMax - tMin;
if tRange == 0
    tPad = abs(tMin)*padFrac + 1e-3;
else
    tPad = padFrac * tRange;
end
xlim(axFull, [tMin - tPad, tMax + tPad]); %[output:5765a154]

% Left axis (pressures)
pAll = [y1_p(:); y2_p(:)];
pMin = min(pAll); pMax = max(pAll);
pRange = pMax - pMin;
if pRange == 0
    pPad = abs(pMin)*padFrac + 1e-3;
else
    pPad = padFrac * pRange;
end
yyaxis(axFull, 'left'); %[output:5765a154]
ylim(axFull, [pMin - pPad, pMax + pPad]); %[output:5765a154]

% Right axis (triggers)
trAll = [y1_tr(:); y2_tr(:)];
trMin = min(trAll); trMax = max(trAll);
trRange = trMax - trMin;
if trRange == 0
    trPad = abs(trMin)*padFrac + 1e-3;
else
    trPad = padFrac * trRange;
end
yyaxis(axFull, 'right'); %[output:5765a154]
ylim(axFull, [trMin - trPad, trMax + trPad]); %[output:5765a154]
box on %[output:5765a154]

% Bottom tile: Window Of Interest (pressures only)
axWoI = nexttile; %[output:5765a154]
% --- Logical indexing first (strict interval) ---
idx1 = find(t1 >= WoI(1) & t1 <= WoI(2));
idx2 = find(t2 >= WoI(1) & t2 <= WoI(2));

% --- Fallback to nearest-index if logical indexing yields empty
if isempty(idx1)
    [~, i0] = min(abs(t1 - WoI(1)));
    [~, i1] = min(abs(t1 - WoI(2)));
    idx1 = min(i0,i1):max(i0,i1);
end
if isempty(idx2)
    [~, j0] = min(abs(t2 - WoI(1)));
    [~, j1] = min(abs(t2 - WoI(2)));
    idx2 = min(j0,j1):max(j0,j1);
end


% Ensure non-empty before plotting
hold(axWoI,'on'); %[output:5765a154]
if ~isempty(idx1)
    axWoIhP1 = plot(axWoI, t1(idx1), y1_p(idx1), '-', 'Color', LUBlue, 'LineWidth', 0.9); %[output:5765a154]
end
if ~isempty(idx2)
    axWoIhP2 = plot(axWoI, t2(idx2), y2_p(idx2), '-', 'Color', LUCopper, 'LineWidth', 0.9); %[output:5765a154]
end
xlabel(axWoI, 'Time [s]', 'Interpreter','latex'); %[output:5765a154]
ylabel(axWoI, 'Overpressure [kPa]', 'Interpreter','latex'); %[output:5765a154]
legend(axWoI,[axWoIhP1,axWoIhP2], ... %[output:5765a154]
    {'Pressure (DAQ-1) '+ ch1_p,'Pressure (DAQ-4) ' + ch2_p}, ... %[output:5765a154]
    'Location','northeast', 'Interpreter','latex'); %[output:5765a154]
title(axWoI, sprintf('Temporal Window of Interest: [%.3f, %.3f] s', WoI(1), WoI(2)), 'Interpreter','latex'); %[output:5765a154]
xlim(axWoI, WoI);  %[output:5765a154]
% --- Dynamic axis limits (5% padding) ---
padFrac = 0.05;

% X limits combining t1 and t2
tAll = [t1(idx1); t2(idx2)];
tMin = min(tAll); tMax = max(tAll);
tRange = tMax - tMin;
if tRange == 0
    tPad = abs(tMin)*padFrac + 1e-3;
else
    tPad = padFrac * tRange;
end
xlim(axWoI, [tMin - tPad, tMax + tPad]); %[output:5765a154]

% Left axis (pressures)
pAll = [y1_p(:); y2_p(:)];
pMin = min(pAll); pMax = max(pAll);
pRange = pMax - pMin;
if pRange == 0
    pPad = abs(pMin)*padFrac + 1e-3;
else
    pPad = padFrac * pRange;
end
ylim(axWoI, [pMin - pPad, pMax + pPad]); %[output:5765a154]
grid(axWoI,'on'); %[output:5765a154]
hold(axWoI,'off'); %[output:5765a154]
% pbaspect(axFull, [16 9 1]);
% axFull.PlotBoxAspectRatioMode = 'manual';
box on %[output:5765a154]
% Add a single shared title above the two tiles
sgtitle(tiled, {"{\textbf{Run Wk22-02-01 (Conc. Target $H_2$ 18 vol.$\%$)}}",'LU vs Kistler DAQs (Flush Mounted Pressure Sensors + RTV)'}, 'Interpreter', 'latex'); %[output:5765a154]
% close all
